			t2_col_d: '<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="ਡਿਕਲੀਨੇਸ਼ਨ ਹਰ ਪਾਰਟੀ ਲਈ ਸੀਟ-ਵੋਟ ਵਕਰ ਵਿਚਕਾਰ ਕੋਣੀ ਫ਼ਰਕ ਮਾਪਦਾ ਹੈ। ਰਿਣਾਤਮਕ ਮੁੱਲ NDP ਦੇ ਹੱਕ ਵਿੱਚ; ਧਨਾਤਮਕ UCP ਦੇ ਹੱਕ ਵਿੱਚ।">ਡਿਕਲੀਨੇਸ਼ਨ</a>',
			t2_col_e: '50/50 ਉੱਤੇ ਸੀਟਾਂ',
			t2_r1_a: 'ਬਹੁ-ਗਿਣਤੀ 2026',
			t2_r1_b: '+0.1% (p16.5)',
